(function(){'use strict';var $=function(id){return document.getElementById(id)},setup=false,videos=[],editing=null,deleting=null,previewUrl=null;
async function api(path,method,body,raw){var r=await fetch(path,{method:method||'GET',headers:body?{'Content-Type':raw?'application/octet-stream':'application/json'}:{},body:body?(raw?body:JSON.stringify(body)):undefined,cache:'no-store'});var d=await r.json();if(!r.ok){if(r.status===401&&path!=='/api/login'){$('dashboard').hidden=true;$('login-panel').hidden=false}throw Error(d.error||'Request failed')}return d}
async function session(){try{var s=await api('/api/session');setup=s.needsSetup;$('login-panel').hidden=s.authenticated;$('dashboard').hidden=!s.authenticated;if(setup){$('login-title').textContent='Admin password သတ်မှတ်မယ်';$('login-hint').textContent=s.canSetup?'ပထမဆုံးအသုံးပြုမှုအတွက် အနည်းဆုံး 12 လုံးပါတဲ့ password သတ်မှတ်ပါ။':'Server ဖွင့်ထားတဲ့ကွန်ပျူတာရဲ့ localhost/admin မှာ password အရင်သတ်မှတ်ပါ။';$('login-submit').textContent='Password သတ်မှတ်မယ်';$('login-submit').disabled=!s.canSetup;$('password').minLength=12;$('password').autocomplete='new-password'}if(s.authenticated)await load()}catch(e){$('login-error').textContent='Server မချိတ်ဆက်နိုင်သေးပါ။'}}
$('login-form').onsubmit=async function(e){e.preventDefault();$('login-submit').disabled=true;try{await api(setup?'/api/setup':'/api/login','POST',{password:$('password').value});$('password').value='';await session()}catch(e){$('login-error').textContent=e.message}finally{$('login-submit').disabled=false}};$('logout').onclick=async function(){try{await api('/api/logout','POST',{});location.reload()}catch(e){$('list-status').textContent=e.message}};
function node(tag,text,cls){var e=document.createElement(tag);if(text)e.textContent=text;if(cls)e.className=cls;return e}
async function load(){try{videos=await api('/api/videos');populateSeries();render()}catch(e){$('list-status').textContent=e.message}}
function populateSeries(){var keep=$('existing-series').value;$('existing-series').textContent='';var fresh=node('option','＋ Series အသစ်');fresh.value='';$('existing-series').append(fresh);LumaSeries.groups(videos).filter(function(g){return g.series}).forEach(function(g){var o=node('option',g.name);o.value=g.name;$('existing-series').append(o)});$('existing-series').value=keep}
function addEpisode(v){reset();$('kind').value='series';category();$('existing-series').value=v.series.trim();$('series').value=v.series.trim();$('series').readOnly=true;var list=LumaSeries.episodes(videos,v);var season=Math.max.apply(null,list.map(function(x){return Number(x.season)||1}));$('season').value=season;$('episode').value=LumaSeries.next(videos,v.series,season);$('thumbnail').value=(list.find(function(x){return x.thumbnail})||{}).thumbnail||'';$('description').value=(list.find(function(x){return x.description})||{}).description||'';$('editor-title').textContent=v.series+' — Episode အသစ်';$('cancel').hidden=false;$('save-status').textContent='Video နာမည်နဲ့ link ဖြည့်ပြီး တင်ပါ။ Season နဲ့ Episode ကိုလည်း ပြောင်းနိုင်ပါတယ်။';$('name').focus();$('video-form').scrollIntoView({block:'start',behavior:'smooth'})}
$('existing-series').onchange=function(){var name=this.value;if(!name){$('series').value='';$('series').readOnly=false;return}var v=videos.find(function(x){return x.kind==='series'&&LumaSeries.key(x.series)===LumaSeries.key(name)});if(v)addEpisode(v)};
$('season').onchange=function(){if(!editing&&$('kind').value==='series'&&$('series').value)$('episode').value=LumaSeries.next(videos,$('series').value,this.value)};
function render(){var q=$('admin-search').value.toLowerCase();$('admin-list').textContent='';$('admin-count').textContent=videos.length;LumaSeries.groups(videos).filter(function(g){return g.items.some(function(v){return(v.name+' '+(v.series||'')+' '+(v.description||'')).toLowerCase().includes(q)})}).forEach(function(g){var group=node('section',null,'admin-series-group');if(g.series){var heading=node('div',null,'series-heading'),title=node('h3',g.name+' · '+g.items.length+' Episodes'),add=node('button','＋ Episode ထည့်မယ်');add.onclick=function(){addEpisode(g.first)};heading.append(title,add);group.append(heading)}g.items.forEach(function(v){var row=node('div',null,'admin-item');if(v.thumbnail){var img=node('img');img.src=v.thumbnail;img.alt='';img.onerror=function(){img.remove()};row.append(img)}var info=node('div',null,'info');info.append(node('strong',v.name),node('p',v.kind==='series'?'Season '+v.season+' · Episode '+v.episode:'Movie'));if(v.description)info.append(node('p','အညွန်း: '+v.description.slice(0,100),'admin-desc'));var actions=node('div',null,'actions'),edit=node('button','ပြင်မယ်'),del=node('button','ဖယ်မယ်');edit.onclick=function(){editVideo(v)};del.onclick=function(){deleting=v;$('delete-name').textContent=v.name;if($('delete-dialog').showModal)$('delete-dialog').showModal();else $('delete-dialog').setAttribute('open','')};actions.append(edit,del);row.append(info,actions);group.append(row)});$('admin-list').append(group)});$('list-status').textContent=videos.length?'':'Video မတင်ရသေးပါ။'}
function category(){$('series-fields').hidden=$('kind').value!=='series';$('series').required=$('kind').value==='series'}$('kind').onchange=category;$('admin-search').oninput=render;
function reset(){editing=null;$('series').readOnly=false;$('existing-series').disabled=false;$('video-form').reset();$('editor-title').textContent='Video အသစ်တင်မယ်';$('save').textContent='တင်မယ်';$('cancel').hidden=true;$('thumb-preview').hidden=true;if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null}category()}
function editVideo(v){reset();editing=v.id;['name','url','thumbnail','kind','series','season','episode','description'].forEach(function(k){$(k).value=v[k]||''});category();$('existing-series').value=v.series||'';$('existing-series').disabled=true;$('editor-title').textContent='Video ပြင်မယ်';$('save').textContent='ပြင်ဆင်မှု သိမ်းမယ်';$('cancel').hidden=false;if(v.thumbnail){$('thumb-preview').src=v.thumbnail;$('thumb-preview').hidden=false}$('name').focus();$('video-form').scrollIntoView({block:'start',behavior:'smooth'})}
$('cancel').onclick=function(){reset();$('save-status').textContent=''};$('thumb-file').onchange=function(){var f=this.files[0];if(previewUrl)URL.revokeObjectURL(previewUrl);if(!f){if($('thumbnail').value.trim()){$('thumb-preview').src=$('thumbnail').value.trim();$('thumb-preview').hidden=false}else $('thumb-preview').hidden=true;return}if(f.size>5*1024*1024){$('save-status').textContent='Thumbnail ကို 5 MB အောက် သုံးပါ။';this.value='';return}previewUrl=URL.createObjectURL(f);$('thumb-preview').src=previewUrl;$('thumb-preview').hidden=false};
$('thumbnail').oninput=function(){if($('thumb-file').files[0])return;var u=this.value.trim();if(u){$('thumb-preview').src=u;$('thumb-preview').hidden=false;$('thumb-preview').onerror=function(){$('thumb-preview').hidden=true}}else $('thumb-preview').hidden=true};
$('video-form').onsubmit=async function(e){e.preventDefault();$('save').disabled=true;$('save-status').textContent='သိမ်းနေပါတယ်…';try{var d={};['name','url','thumbnail','kind','series','season','episode','description'].forEach(function(k){d[k]=$(k).value});if(d.kind==='series'){var duplicate=videos.find(function(v){return v.id!==editing&&LumaSeries.same(v,d)&&Number(v.season)===Number(d.season)&&Number(v.episode)===Number(d.episode)});if(duplicate)throw Error('ဒီ Season / Episode ရှိပြီးသားပါ။ အဲဒီအပိုင်းကို ပြင်မယ် ကနေ ပြင်ပါ။')}var f=$('thumb-file').files[0];if(f){var upload=await api('/api/thumbnails','POST',f,true);d.thumbnail=upload.url}await api(editing?'/api/videos/'+editing:'/api/videos',editing?'PUT':'POST',d);reset();$('save-status').textContent='သိမ်းပြီးပါပြီ။ ကြည့်ရှုသူစာမျက်နှာကို ပြန်ဖွင့်ရင် တွေ့နိုင်ပါပြီ။';await load()}catch(e){$('save-status').textContent=e.message}finally{$('save').disabled=false}};
function closeDelete(){if($('delete-dialog').close)$('delete-dialog').close();else $('delete-dialog').removeAttribute('open');deleting=null}$('cancel-delete').onclick=closeDelete;$('confirm-delete').onclick=async function(){if(!deleting)return;var id=deleting.id;try{await api('/api/videos/'+id,'DELETE');closeDelete();if(editing===id)reset();await load()}catch(e){$('delete-name').textContent=e.message}};session();})();
